import numpy as np
from PIL import Image

arr13 = np.array(Image.open('/work/observations/obs_0013.png').convert('RGB'))
chair_m = (arr13[:, :100, 0] > 70) & (arr13[:, :100, 0] < 160) & (arr13[:, :100, 1] > 30) & (arr13[:, :100, 1] < 90) & (arr13[:, :100, 2] < 50) & (arr13[:, :100, 0] > arr13[:, :100, 1] + 20)
